"""Write a concise, evidence-based report for an audited strict replay run."""
import argparse,json
from collections import Counter
from pathlib import Path
import numpy as np


def summarize(folder):
 folder=Path(folder);r=json.loads((folder/'results.json').read_text());s=json.loads((folder/'settings.json').read_text());v=json.loads((folder/'verification.json').read_text());rows=r['results'];fail=[x for x in rows if x['outcome']!='success'];max_force={k:max(x['audit']['contact_audit'][k]['max_normal_force_N']for x in rows)for k in ['robot_self','finger_table','cube']};max_depth={k:max(x['audit']['contact_audit'][k]['max_penetration_m']for x in rows)for k in ['robot_self','finger_table','cube']}
 success=r['successes'];total=r['completed'];adapter=s['adapter'];mat=s['measurements']['mat'];lines=[f'# Strict native-action replay: {success}/{total} task passes','',f'All {total} episodes completed with {r["errors"]} runtime errors. Task pass rate: **{success/total:.1%}**. **This is not a physically validated digital twin or a proven sim-to-real transfer result.**','', '## What was replayed','',f'- All **{v["verified_frames"]:,} original six-channel actions** and **{v["verified_physics_steps"]:,} physics steps** verified. One frozen settings hash is shared across episodes.', '- Arm channels are degrees. Gripper is normalized0–100, with the encoder-derived scale **1.298461538degrees/native unit**. No input clipping, trajectory repair, IK, grasp retiming, state-following after initialization, weld, object teleportation or applied holding force.',f'- Fixed model gripper closed reference: **{adapter["gripper_closed_model_deg"]:.6f}degrees**. This mechanical reference remains an identified estimate, separate from the known encoder scale.', '- Motors use identified position response and causal delay history. The pre-recording history is initialized to the observed initial pose because older commands are unavailable.', '- Cube poses are initialized from the first real top image using the measured-size3D silhouette. Later cube motion comes only from MuJoCo. Initial scene positions vary with the real scene; physical calibration does not vary by episode.','', '## Geometry and contact','', '- User measurements: cube19.5×19.5×19.5mm; bowl outer rim diameter118mm, height50mm; mat405×405×2mm; standard SO-101 fingers, base resting directly on tabletop.', '- Model base body origin is3.4mm above world zero: table top1mm plus2.4mm from the source mesh underside to its body frame. There is no added riser or base tilt.', '- Source arm/finger/workcell collisions are active. Distal fixed/moving jaw pairs explicitly override MuJoCo parent filtering. Normal same-body and connected-hinge filtering remains. Added pad proxies are disabled.',f'- Initial maximum overlap: **{v["initial_max_penetration_m"]*1000:.6f}mm**.', f'- Bowl bottom outer diameter: {s["estimates"]["bowl_bottom_outer_radius_m"]*2000:g}mm ({"user measured" if s["measurements"]["bowl"].get("bottom_diameter") else "estimated"}). Cube mass4.449g assumes wood density600kg/m³. Wall3mm, floor4mm, friction and motor properties remain estimates.','', '| Contact category | Maximum normal force | Maximum penetration, including transients |','|---|---:|---:|']
 for k in max_force:lines.append(f'| {k} | {max_force[k]:.3f}N | {max_depth[k]*1000:.3f}mm |')
 lines +=['', '## Task criteria','', '- Lift at least40mm above initial cube center.', '- Continuous bilateral normal force of at least0.02N per jaw, with jaw/cube penetration at most1.5mm: at least80ms of secure grasp and30ms of secure lift.', '- All8 cube corners inside the physical bowl, no final finger support, final linear speed≤0.03m/s and angular speed≤0.3rad/s, and less than3mm translation over the last10samples.', '- Score is measured after executing the final source action for one nominal30Hz interval. Videos show the originalN observation frames; terminalN+1 physics state is stored in the trace.', '', '## Results', '', '| Outcome | Count |','|---|---:|']
 for key,count in r['counts'].items():lines.append(f'| {key} | {count} |')
 lines +=['', 'Failed episodes: '+', '.join(f'{x["episode"]} ({x["outcome"]})'for x in fail)+'.','', '## Video and reproduction','']
 videos=sorted(folder.glob('episode-*/real-vs-sim-strict.mp4'))
 render_ids=' '.join(str(int(video.parent.name.split('-')[-1]))for video in videos) or '0'
 for video in videos:
  i=int(video.parent.name.split('-')[-1])
  if video.exists():lines.append(f'- [Episode{i}: {next(x["outcome"] for x in rows if x["episode"]==i)}](episode-{i:02d}/real-vs-sim-strict.mp4) — full top/wrist real-versus-sim comparison.')
 lines +=['',f'Camera observation delays: {s.get("camera_delay_frames",{})} frames, using only earlier integrated states. They are rounded image-fit estimates, not measured exposure timestamps. Actuator commands retain their original timing.','', '```sh',f'.venv/bin/python scripts/strict_action_replay.py --config {folder}/settings.json --output output/reproduction', '.venv/bin/python scripts/audit_strict_action.py --output output/reproduction', f'.venv/bin/python scripts/strict_action_replay.py --output output/reproduction --render-only --episodes {render_ids}','```','', 'macOS rendering requires desktop graphics access. Playback uses the archived model selected by current metadata, with XML/trace hashes checked. Shared STL assets, source snapshots, original dataset and calibration hashes are retained.','', '## Remaining uncertainty','', '- Camera intrinsics/distortion/exposure timing, historical absolute robot reference calibration, finger compliance, motor response, contact friction and object mass are not fully measured. A successful replay is not evidence that a new policy is safe or reliable on the real robot.', '- Multiple global parameter fits were evaluated. Training/other-episode diagnostics are not a blind generalization experiment: earlier outcomes and all initial poses were inspected during development.', '- Fits that increased task passes through large initial overlap were rejected. Later fits can improve native state error while reducing task passes; those alternatives remain separate experimental artifacts.', '- Commands were not sent to the physical robot. The native action/state conversion contract is explicit and invertible, but hardware policy transfer remains unvalidated.','']
 (folder/'RESULTS.md').write_text('\n'.join(lines));summary={'successes':success,'total':total,'rate':success/total,'failed_episodes':[x['episode']for x in fail],'counts':r['counts'],'max_contact_normal_force_N':max_force,'max_contact_penetration_m':max_depth,'native_action_changed':False,'physically_validated_successes':None};(folder/'summary.json').write_text(json.dumps(summary,indent=2));print(json.dumps(summary,indent=2))

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--output',required=True);summarize(p.parse_args().output)
